    public record Recipe(String key,String research,boolean self,int infusion,int instability,AspectList cost,List<TcIngredient> ingredients,String input,String output){
        public Recipe(String key,String research,boolean self,int infusion,int instability,AspectList cost,List<TcIngredient> ingredients){this(key,research,self,infusion,instability,cost,ingredients,"","");}
        public boolean transformation(){return !output.isEmpty();}
        public LivingEntity apply(LivingEntity subject,UUID operator,AspectList cost){return transformation()?Species.transform(subject,output,cost):Infusions.add(subject,infusion,operator,cost)?subject:null;}
    }
    private static final Map<String,Recipe> ALL=new LinkedHashMap<>();
    private static void add(Recipe recipe){ALL.put(recipe.key(),recipe);}
    public static Collection<Recipe> all(){return Collections.unmodifiableCollection(ALL.values());}
    public static Recipe get(String key){return ALL.get(key);}
    public static boolean matches(List<TcIngredient> needed,List<ItemStack> supplied){
        if(needed.size()!=supplied.size())return false;
        return match(needed,supplied,new boolean[supplied.size()],0);
    }
    private static boolean match(List<TcIngredient> needed,List<ItemStack> supplied,boolean[] used,int index){
        if(index==needed.size())return true;
        for(int i=0;i<supplied.size();i++)if(!used[i]&&needed.get(index).test(supplied.get(i))){used[i]=true;if(match(needed,supplied,used,index+1))return true;used[i]=false;}return false;
    }
    public static Recipe find(List<ItemStack> items,boolean self,LivingEntity subject,Player player,int[] shell){
        for(Recipe recipe:ALL.values())if(recipe.self()==self&&ResearchManager.isComplete(player,recipe.research())&&(recipe.transformation()?Species.accepts(recipe.input(),subject):!(self?Arrays.stream(shell).anyMatch(n->n==recipe.infusion()):Infusions.has(subject,recipe.infusion())))&&matches(recipe.ingredients(),items))return recipe;return null;
    }
    public static boolean stabilizer(net.minecraft.world.level.Level level,net.minecraft.core.BlockPos pos){var block=level.getBlockState(pos).getBlock();return block instanceof net.minecraft.world.level.block.AbstractSkullBlock||block instanceof thaumcraft.block.InfusionStabiliser stabilizer&&stabilizer.canStabiliseInfusion(level,pos);}
